  // ---- lineup efficiency ----
  function lineUnitsHtml() { if (!ST.base) return ''; const X = current(); if (!X.P.trackLines) return ''; const T = MS.lineTable(X.r.games).filter(r => r.poss), avg = T.reduce((a, r) => ({ poss: a.poss + r.poss, sh: a.sh + r.sh, sog: a.sog + r.sog, g: a.g + r.g, to: a.to + r.to }), { poss: 0, sh: 0, sog: 0, g: 0, to: 0 }); return T.length ? `<h3>This run: efficiency by six on the field</h3><div class="wrap"><table><thead><tr><th class="l">Six on the field</th><th>Poss/game</th><th>Goals /100</th><th>Shots /100</th><th>TO /100</th><th>On goal</th><th>Finish</th><th class="l">Why, vs the team, goals per 100</th></tr></thead><tbody>${T.map(r => `<tr><td class="l">${esc(r.players.join(', '))}</td><td>${num(r.possPerGame)}</td><td>${num(r.goalsPer100)}</td><td>${num(r.shotsPer100)}</td><td>${num(r.turnoversPer100)}</td><td>${pct(r.onGoal)}</td><td>${pct(r.finish)}</td><td class="l reason">${esc(MS.sixWhyText(MS.sixWhy(r, avg), 'the team'))}</td></tr>`).join('')}</tbody></table></div><p class="sub" style="margin:6px 0 0">Per 100 possessions that began with that six on the field. Only the current rotation’s lines.</p>` : ''; }
  function effHtml() { const r = ST.rotation, E = ST.eff, pool = ST.effPool || (ST.effPool = [...new Set(r.lines.flatMap(l => l.players))]), Ms = byPos(p => /[MF]/.test(p)), n = pool.length, combos = n >= 3 ? n * (n - 1) * (n - 2) / 6 : 0, big = combos > 56; return `<div class="panel"><h2>Most efficient lineups</h2><p class="sub">Choose a midfield pool. Every three-man midfield from it plays every offensive possession with the current attack, on the same seeds. Efficiency is goals per 100 offensive possessions. Only these are tested, and player effects add up: no measured chemistry, because lineup logs are too thin. No game validation applies.</p><div class="grp"><h3>Midfield pool: ${n} players, ${combos} lineups</h3><div class="row">${Ms.map(j => `<button type="button" class="pill small${pool.includes(j) ? ' on' : ''}" data-eff="${esc(j)}">${esc(nameOf(j))}</button>`).join('')}</div></div>${big ? '<p class="err">Keep it to 8 players (56 lineups).</p>' : ''}<button class="go" id="runEff" ${ST.busy || combos < 2 || big || rotationProblems(r).length ? 'disabled' : ''}>Test ${combos} lineups</button>${E ? `<h3>Highest projected among ${E.tested} tested lineups, attack ${esc(E.attack.join(', '))}</h3><div class="wrap"><table><thead><tr><th class="l">Midfield</th><th>Goals /100</th><th>Shots /100</th><th>TO /100</th><th>On goal</th><th>Finish</th><th>Fresh-seed win</th><th>vs top</th><th>SE</th><th>Read</th><th class="l">Why, vs the average tested lineup</th></tr></thead><tbody>${E.rows.map(x => `<tr><td class="l">${esc(x.players.map(nameShort).join(', '))}</td><td>${num(x.g100)}</td><td>${num(x.s100)}</td><td>${num(x.t100)}</td><td>${pct(x.q)}</td><td>${pct(x.r)}</td><td>${x.fresh === null ? '—' : pct(x.fresh)}</td><td>${x.diff === null ? '—' : ((100 * x.diff >= 0 ? '+' : '') + (100 * x.diff).toFixed(1) + ' pts')}</td><td>${x.se === null ? '—' : (100 * x.se).toFixed(1)}</td><td>${esc(x.read)}</td><td class="l reason">${esc(x.why)}</td></tr>`).join('')}</tbody></table></div><p class="sub" style="margin:6px 0 0">Screened on ${E.screen.toLocaleString()} games each; the top ${E.finalists} rerun on ${E.fresh.toLocaleString()} fresh-seed games. Each six plays as if it were on for every offensive possession, which no real game would do.</p>` : ''}</div>`; }
  const nameShort = j => `#${j} ${(ST.names[j] || '').split(' ').slice(-1)[0]}`.trim();
  async function runEff() {
    if (ST.busy) return; ST.busy = true; ST.cancel = false; const keep = ST.rotation, pool = ST.effPool.slice(), sets = []; for (let a = 0; a < pool.length; a++) for (let b = a + 1; b < pool.length; b++) for (let c = b + 1; c < pool.length; c++) sets.push([pool[a], pool[b], pool[c]]); const screen = 400, fresh = 2000, finalists = Math.min(5, sets.length), total = sets.length * screen + finalists * fresh; let done = 0; ST.progress = { label: 'Lineups', done: 0, total }; renderHdr(); const res = [];
    try { for (const mids of sets) { if (ST.cancel) break; ST.rotation = Object.assign({}, keep, { lines: [{ players: mids, share: 1 }] }); const c = compileBase(), Q = applyOverrides(c.P); Q.trackLines = true; const r = await runOne(Q, screen, ST.seed, `Lineup ${mids.join(', ')}`, done, total); done += screen; const L = MS.lineTable(r.games), tot = L.reduce((a, x) => ({ poss: a.poss + x.poss, sh: a.sh + x.sh, sog: a.sog + x.sog, g: a.g + x.g, to: a.to + x.to }), { poss: 0, sh: 0, sog: 0, g: 0, to: 0 }); res.push({ mids, Q, tot, win: r.summary.teams[0].winProbability }); } const all = res.reduce((a, x) => ({ poss: a.poss + x.tot.poss, sh: a.sh + x.tot.sh, sog: a.sog + x.tot.sog, g: a.g + x.tot.g, to: a.to + x.tot.to }), { poss: 0, sh: 0, sog: 0, g: 0, to: 0 }); res.sort((a, b) => b.tot.g / b.tot.poss - a.tot.g / a.tot.poss); const top = res.slice(0, finalists); let best = null; for (const x of top) { if (ST.cancel) break; const r = await runOne(x.Q, fresh, ST.seed + 1, `Fresh seeds ${x.mids.join(', ')}`, done, total); done += fresh; x.fr = r; } const withFr = top.filter(x => x.fr).sort((a, b) => b.fr.summary.teams[0].winProbability - a.fr.summary.teams[0].winProbability); best = withFr[0]; const rows = res.slice(0, 12).map(x => { const d = x.fr && best && x !== best ? paired({ r: best.fr }, { r: x.fr }, g => (g.box.winner === 0 ? 1 : 0)) : null, t = x.tot; return { players: x.mids, g100: 100 * t.g / t.poss, s100: 100 * t.sh / t.poss, t100: 100 * t.to / t.poss, q: t.sog / t.sh, r: t.g / t.sog, fresh: x.fr ? x.fr.summary.teams[0].winProbability : null, diff: d ? d.mean : null, se: d ? d.se : null, read: !x.fr ? 'Not rerun' : x === best ? 'Top of those rerun' : Math.abs(d.mean) < 2 * d.se ? 'Effectively tied' : 'Projected lower', why: MS.sixWhyText(MS.sixWhy(t, all), 'the average') }; }).sort((a, b) => (b.fresh ?? -1) - (a.fresh ?? -1) || b.g100 - a.g100); ST.eff = { rows, tested: res.length, attack: keep.attack, screen, fresh, finalists }; } catch (e) { ST.msg = 'Lineup test failed: ' + e.message; }
    ST.rotation = keep; ST.busy = false; ST.progress = null; render();
  }
  // ---- rendering and events ----
  const TABS = [['overview', 'Overview'], ['why', 'Why'], ['players', 'Players'], ['lineups', 'Lineups'], ['goalies', 'Goalies'], ['inputs', 'Inputs'], ['game', 'This game']];
  function paintProgress() { const el = $('prog'); if (!el) return; const p = ST.progress; el.innerHTML = p ? `<div class="sub" style="margin:0 0 4px">${esc(p.label)}: ${p.done.toLocaleString()} of ${p.total.toLocaleString()} games completed</div><div class="bar"><i style="width:${(100 * p.done / Math.max(1, p.total)).toFixed(1)}%"></i></div>` : ''; }
  function bodyOf() { return ST.tab === 'overview' ? overviewHtml() : ST.tab === 'why' ? whyHtml() : ST.tab === 'players' ? playersHtml() : ST.tab === 'lineups' ? lineupsHtml() : ST.tab === 'goalies' ? goaliesHtml() : ST.tab === 'inputs' ? inputsHtml() : gameHtml(); }
  function renderHdr() { $('hdr').innerHTML = headerHtml() + `<p style="margin:8px 0 0"><a class="pill" href="gameweek.html" style="text-decoration:none;display:inline-block">← Back to the game week sheet</a></p><div class="tabs" role="tablist">${TABS.map(([k, l]) => `<button class="tab${ST.tab === k ? ' on' : ''}" role="tab" data-tab="${k}">${l}</button>`).join('')}</div>`; paintProgress(); bind(); }
  function renderBody() { const active = document.activeElement && document.activeElement.dataset ? document.activeElement.dataset.ov : null; $('body').innerHTML = bodyOf(); bind(); bindTips(); if (active) { const el = document.querySelector(`[data-ov="${active}"]`); if (el) { el.focus(); const v = el.value; el.value = ''; el.value = v; } } }
  function render() { renderHdr(); renderBody(); paintGames(); }   // the field isn't touched: it keeps playing while tabs change
  function toggleRot(key, j) {
    const r = ST.rotation; if (key === 'goalie') { r.goalie = r.goalie === j ? null : j; return; } const L = rotList(key), i = L.indexOf(j); if (i >= 0) L.splice(i, 1); else L.push(j);
  }
  function resetResults() { ST.base = null; ST.scen = null; ST.cmp = null; ST.whatIf = null; ST.goalieRun = null; ST.eff = null; ST.showControls = true; }
  function bind() {
    const on = (sel, f) => document.querySelectorAll(sel).forEach(f);
    on('[data-tab]', b => { b.onclick = () => { ST.tab = b.dataset.tab; render(); }; });
    on('[data-mode]', b => { b.onclick = () => { if (ST.mode !== b.dataset.mode) { ST.mode = b.dataset.mode; ST.ov = {}; resetResults(); render(); } }; });
    on('[data-opp]', b => { b.onclick = () => { ST.opp = b.dataset.opp; resetResults(); render(); }; }); on('[data-cohort]', b => { b.onclick = () => { ST.cohort = b.dataset.cohort; resetResults(); render(); }; });
    on('[data-ta]', b => { b.onclick = () => { ST.teamA = b.dataset.ta; if (ST.teamB === ST.teamA) ST.teamB = ST.teamList.find(t => t !== ST.teamA); resetResults(); render(); }; }); on('[data-tb]', b => { b.onclick = () => { ST.teamB = b.dataset.tb; resetResults(); render(); }; });
    on('[data-games]', b => { b.onclick = () => { ST.games = Number(b.dataset.games); render(); }; }); on('[data-view]', b => { b.onclick = () => { ST.view = b.dataset.view; openReplay(current(), ST.replay ? ST.replay.index : 0, ST.player ? ST.player.st.playing : false); render(); }; }); on('[data-sort]', b => { b.onclick = () => { ST.sortKey = b.dataset.sort; render(); }; });
    const sd = $('seed'); if (sd) sd.onchange = () => { ST.seed = Math.max(1, Math.floor(Number(sd.value)) || 1); }; const run = $('run'); if (run) run.onclick = runMatchup; const can = $('cancel'); if (can) can.onclick = () => { ST.cancel = true; };
    on('[data-ov]', el => { el.onchange = () => { const k = el.dataset.ov; if (el.value === '') delete ST.ov[k]; else ST.ov[k] = el.value; render(); }; }); on('[data-reset]', b => { b.onclick = () => { delete ST.ov[b.dataset.reset]; render(); }; }); const ra = $('resetAll'); if (ra) ra.onclick = () => { ST.ov = {}; render(); };
    on('[data-rot]', b => { b.onclick = () => { toggleRot(b.dataset.rot, b.dataset.j); render(); }; }); on('[data-share]', el => { el.onchange = () => { ST.rotation.lines[Number(el.dataset.share)].share = Number(el.value) / 100; render(); }; });
    const al = $('addLine'); if (al) al.onclick = () => { ST.rotation.lines.push({ players: [], share: 0.2 }); render(); }; const dl = $('dropLine'); if (dl) dl.onclick = () => { ST.rotation.lines.pop(); render(); };
    const sr = $('saveRot'); if (sr) sr.onclick = () => { const nm = ($('rotName').value || '').trim() || `Rotation ${ST.tested.length + 1}`; ST.tested.push({ name: nm, rotation: JSON.parse(JSON.stringify(ST.rotation)) }); render(); }; const rr = $('resetRot'); if (rr) rr.onclick = () => { ST.rotation = JSON.parse(JSON.stringify(ST.fixtureRotation)); render(); };
    on('[data-load]', b => { b.onclick = () => { ST.rotation = JSON.parse(JSON.stringify(ST.tested[Number(b.dataset.load)].rotation)); render(); }; }); on('[data-del]', b => { b.onclick = () => { ST.tested.splice(Number(b.dataset.del), 1); render(); }; }); const rc = $('runCmp'); if (rc) rc.onclick = runCompare; const sc = $('showCtl'); if (sc) sc.onclick = () => { ST.showControls = true; renderHdr(); }; const rw = $('runWhy'); if (rw) rw.onclick = runWhatIfs; const rg = $('runGoalies'); if (rg) rg.onclick = runGoalies; const re = $('runEff'); if (re) re.onclick = runEff; on('[data-eff]', b => { b.onclick = () => { const j = b.dataset.eff, P = ST.effPool, i = P.indexOf(j); if (i >= 0) P.splice(i, 1); else P.push(j); renderBody(); }; });
    const fd = $('fileData'); if (fd) fd.onchange = async () => { const f = fd.files[0]; if (!f) return; try { const j = JSON.parse(await f.text()); ST.official = j; ST.version = j.version || null; setupOfficial(); render(); } catch (e) { ST.msg = 'That file couldn’t be read.'; render(); } };
  }
  window.__MS_RUN = { runMatchup, runCompare, runWhatIfs, runGoalies, runEff, render, renderHdr, renderBody, openReplay, applyOverrides, compileBase, rotationProblems, current };
